# Generated by a one-off converter (outside this repo). Edit by hand only after review.
EXAM = "AI-200"
EXAM_TITLE = "Developing AI Cloud Solutions on Azure"
STUDY_GUIDE = "https://learn.microsoft.com/credentials/certifications/resources/study-guides/ai-200"
# Imported banks have one explanation per question and no per-choice rationale.
IMPORTED_SINGLE_EXPLANATION = True
RELAXED_STYLE = True

# Source: MichaelAanraad/ai200-practice index.html (inline items plus window.__BANKS), converted 2026-11-18.
DOMAINS = {
    "1": ("Containerized solutions", "20-25%"),
    "2": ("Data services for AI", "25-30%"),
    "3": ("Connect & consume services", "20-25%"),
    "4": ("Secure, monitor & troubleshoot", "20-25%"),
}
# group id: (title, questions per objective, objectives); OVERRIDE holds the real counts
GROUPS = {
    "1.1": ("Containerized solutions", 0, [
        "Containerized solutions",
    ]),
    "2.1": ("Data services for AI", 0, [
        "Data services for AI",
    ]),
    "3.1": ("Connect & consume services", 0, [
        "Connect & consume services",
    ]),
    "4.1": ("Secure, monitor & troubleshoot", 0, [
        "Secure, monitor & troubleshoot",
    ]),
}
TOTAL = 953  # question bank size; validate.py and build.py check against it
OVERRIDE = {
    "1.1.1": 235,
    "2.1.1": 250,
    "3.1.1": 233,
    "4.1.1": 235,
}


def objectives():
    """{objective id: (text, target count)}"""
    out = {}
    for g, (_, n, objs) in GROUPS.items():
        for i, text in enumerate(objs, 1):
            oid = f"{g}.{i}"
            out[oid] = (text, OVERRIDE.get(oid, n))
    return out


if __name__ == "__main__":
    o = objectives()
    by_dom = {d: sum(n for k, (_, n) in o.items() if k[0] == d) for d in DOMAINS}
    print(len(o), "objectives,", sum(n for _, n in o.values()), "questions", by_dom)
    assert sum(n for _, n in o.values()) == TOTAL
    for g, (title, n, objs) in GROUPS.items():
        print(g, title, [o[f"{g}.{i}"][1] for i in range(1, len(objs) + 1)])
